BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
L=['拉丁语 pavire','敲打、夯实、踩实']
P=[L,['通俗拉丁拟构形式 *pavare；另有经名词 pavement 逆构的分析','古法语动词的更早来历有不同解释'],['古法语 paver','铺设坚实表面'],['中古英语 paven → 英语 pave','铺路、铺地；比喻为后续发展铺路']]
W=[
E('pave','/peɪv/','铺路；铺设硬质表面；为……铺平道路','把原来的地面变成可以走、可以行驶的坚实表面。','来自古法语 paver，通常接拟构通俗拉丁 *pavare、拉丁 pavire“夯实”；也有从法语名词 pavement 逆构的解释。英语比喻 pave the way 接的是铺好路后更容易前进的画面。',P,'pave a courtyard 是给院子铺上石材、砖或其他硬面，不必一定用沥青。pave the way for cooperation 则是让后续合作更容易发生，可能通过建立信任、清除程序障碍等。','pave a road；pave a courtyard with stone；pave the way for something。','build a road 可以包含整条道路工程；pave 重点在铺设表面。pave the way 说创造条件，不保证后面的事情必然成功。',('They paved the narrow path with reclaimed bricks.','他们用回收的砖铺了那条小路。'),('The agreement paved the way for closer cooperation.','这项协议为更紧密的合作铺平了道路。'),sources=['https://www.etymonline.com/word/pave','https://en.wiktionary.org/wiki/pave']),
E('pavement','/ˈpeɪvmənt/','人行道〔英〕；铺设的路面〔美等用法〕','先想到铺好的硬地面，再根据地区判断是在路边还是车轮下面。','历史上经法语 pavement 和拉丁 pavimentum 借入，后者接 pavire“夯实”。现代能联系 pave + -ment，但英语名词有独立且较早的借入史。',[L,['拉丁语 pavimentum','夯实的地面、硬质地面'],['古法语、盎格鲁法语 pavement；亦有直接拉丁借入','铺好的路面'],['中古英语 pament、pavement → 英语 pavement','铺设表面；英式常特指路边人行道']],'英国街上有人说 stay on the pavement，通常要你留在人行道上。美国材料谈 damaged pavement，则常在说铺装路面破损。相同词根保留了“硬质地面”，各地的常用范围却不同。','walk on the pavement；a narrow pavement；cracks in the pavement；pavement markings。','英国 pavement 的人行道义常对应美国 sidewalk；美国 pavement 不能一律译成人行道。判断时先看地点和实际场景。',('A delivery van was blocking the pavement outside the shop.','一辆送货车堵住了商店外的人行道。'),('The road crew repaired several cracks in the pavement.','道路施工队修补了路面的几处裂缝。'),sources=['https://www.etymonline.com/word/pavement','https://www.oxfordlearnersdictionaries.com/definition/english/pavement']),
E('paved','/peɪvd/','已铺设硬面的；铺好的','原来可能是土、沙或碎石的表面，如今已经铺好。','pave 的过去式、过去分词，也作形容词；中古英语已有 paved、ypavyd 等形式。结尾 -ed 读 /d/。',P[:-1]+[['中古英语 paven → paved、ypavyd','铺设 → 已铺设的'],['英语 paved','铺好的；动词 pave 的过去式、过去分词']],'a paved path 说明有铺装表面，并不自动保证它宽阔、平坦或适合汽车。句子 they paved the path 中则是过去式，叙述他们完成铺路这件事。','a paved road；a paved courtyard；a paved path；be paved with stone。','paved 说是否铺装，smooth 说是否平滑。铺过的旧路仍可能坑坑洼洼，所以两个形容词不能互相替代。',('A paved path connects the station to the river.','一条铺好的步道连接着车站和河边。'),('The courtyard was paved with large grey stones.','院子铺着大块灰色石板。'),sources=['https://en.wiktionary.org/wiki/paved','https://www.etymonline.com/word/pave']),
E('paving','/ˈpeɪvɪŋ/','铺路、铺地；铺路材料；铺好的地面','可以谈正在做的铺设工作，也可以谈脚下整片铺面和所用材料。','英语 pave 去掉词尾 e 加 -ing。作动词形式时说正在铺；作名词时，动作名称又能指工作成果和材料。',P+[['英语 pave + -ing → paving','铺设的动作；铺面及铺设材料']],'The paving is uneven 中，paving 是已经铺好的表面，不是在说动作进行得不整齐。paving work 才明确指施工工作；paving stones 是铺路石。','stone paving；concrete paving；paving work；lay paving；paving slabs。','paving 常是不可数的材料或整体铺面；单独数一块块铺砖时可以用 pavers 或 paving stones。',('Moss grew between the stones in the old paving.','旧铺面石块的缝隙间长出了青苔。'),('Paving work will begin after the drainage pipes are installed.','排水管安装完毕后将开始铺路施工。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/paving','https://en.wiktionary.org/wiki/paving']),
E('unpaved','/ʌnˈpeɪvd/','未铺硬面的；未铺装的','路已经在那里，但表面还不是沥青、混凝土或铺砖等铺装面。','否定前缀 un- + paved；这里 un- 说没有那种状态，不表示把已铺好的路面拆掉。',P+[['英语 paved → un- + paved','铺好的 → 未铺装的'],['英语 unpaved','表面没有铺装的']],'an unpaved road 可以是土路，也可能铺了碎石，不能只凭这个词判断完全没有维护。重点是与正式铺装的表面相比，路面性质不同。','an unpaved road；an unpaved track；an unpaved section；an unpaved parking area。','unfinished 说工程未完成；unpaved 说没有铺装。某条碎石路可能已经按计划完工，却仍是 unpaved。',('The last kilometre to the farmhouse is unpaved.','通往农舍的最后一公里是未铺装路段。'),('Dust rose behind the bus on the unpaved road.','公交车驶过未铺装道路，车后扬起了尘土。'),sources=['https://www.etymonline.com/word/unpaved','https://en.wiktionary.org/wiki/unpaved']),
E('paver','英 /ˈpeɪvə/；美 /ˈpeɪvər/','铺路砖、铺路石；铺路工；摊铺机','在家装材料里常是一块铺地砖，在工地语境里也可能是铺路的人或机器。','英语 pave + -er。-er 可指实施动作的人或设备；paver 还发展出供铺设使用的一块石、砖或混凝土块的意思。',P+[['英语 pave + -er → paver','铺路的人；后来也指铺路材料块和设备']],'买 twenty pavers，通常是在买二十块铺地砖，不是雇二十个工人。a paver moving slowly down the road 则可能是施工设备；数量、材料和动作会帮你确定是哪种。','concrete pavers；brick pavers；lay pavers；an asphalt paver。','paving 是整体材料或铺面，paver 可以单独数一块。paver 也不保证是天然石材，混凝土制品同样可以这样叫。',('We laid square concrete pavers across the garden path.','我们沿花园小径铺了方形混凝土砖。'),('An asphalt paver moved slowly ahead of the roller.','一台沥青摊铺机在压路机前方缓慢移动。'),sources=['https://www.etymonline.com/word/paver','https://www.merriam-webster.com/dictionary/paver'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(r for r in m['roots']if r['id']=='C0975');family=r['family'];keep={w['word']for w in W}
excluded={'pavior':'按用户范围暂略少用的铺路工称呼，保留 paver。','pavage':'按用户范围暂略历史铺路税术语。'}
ROOT=[dict(id='C0975',meaning='敲打、夯实；铺路',core='pav-：把地面打实、铺好，进一步比喻让后面的事情好走。',image='把松散地面夯实、铺上砖石，脚下就有了一条路。',intro='拉丁 pavire 表示敲打、踩实，英语这一组集中在铺设表面。pave 是动作，paved 与 unpaved 描述状态，paving 可以说材料或铺面，paver 可以数一块铺砖；pavement 则要注意英美常用义的差别。',forms='pavement 经法语、拉丁名词独立借入；paved、paving、paver 等则能直接联系英语 pave 的派生。',branches=[['铺设动作和比喻','pave、paving'],['表面与材料','pavement、paver'],['是否已铺装','paved、unpaved']],contrasts='pavement 在英国常指人行道，在美国常说铺装路面。paved 不保证 smooth；unpaved 也不一定等于工程未完成。',practice='比较 a paved path、stone paving 和 twenty pavers，再用 pave the way 写一句比喻。',words=[w for w in family if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/pave','https://www.etymonline.com/word/pavement'])]
assert keep==set(family)-set(excluded)
